    /**
     * A claim as the screen shows it; the amount always carries two decimals. The settled due is the figure fixed
     * when it was settled, or null while its due is live. Opened-by is the user who opened it, or null. Stated is
     * whether its person's last statement binds it, to the stated due (null for n/a). Corrects is the number of the
     * claim a correction corrects, or null. Rounds-on is the date its rounding follows: its own, or for a correction
     * the date of the claim it corrects. Deferred-until is the date it was deferred until, or null; it is deferred
     * while it is OPEN and the sheet's today is before that date. Proofs is how many proofs it has. Split-from is the number of the claim it was split off, or null. Log is its status log, oldest first.
     * Locked-by is the user whose open editor holds it, or null.
     */
    public record ClaimView(Long id, Long personId, String amount, LocalDate date, String note, ClaimStatus status,
            String number, String settledDue, String openedBy, boolean stated, String statedDue, String corrects,
            LocalDate roundsOn, LocalDate dueBy, LocalDate deferredUntil, int proofs, String splitFrom, List<LogLineView> log,
            String lockedBy) {
        public static ClaimView of(Claim c) {
            return new ClaimView(c.getId(), c.getPersonId(), c.getAmount().toPlainString(), c.getDate(), c.getNote(),
                    c.getStatus(), c.getNumber(), c.getSettledDue() == null ? null : c.getSettledDue().toPlainString(),
                    c.getOpenedBy(), c.isStated(), c.getStatedDue() == null ? null : c.getStatedDue().toPlainString(),
                    c.getCorrects(), c.getRoundsOn(), c.getDueBy(), c.getDeferredUntil(), c.getProofs(), c.getSplitFrom(), c.getLog().stream().map(LogLineView::of).toList(),
                    c.getLockedBy());
        }
    }

    /** A line of a claim's status log: the status, who made the change, the sheet's today then, and the due then. */
  settledDue: string | null;
  // The user who opened the claim; null for a claim never opened. That user cannot settle it.
  openedBy: string | null;
  // Whether the person's last statement binds the claim, and the figure it binds it to (null for n/a).
  stated: boolean;
  statedDue: string | null;
  // The number of the settled claim a correction (a negative amount) corrects; null for any other claim.
  corrects: string | null;
  // The date the claim's rounding follows: its own, or for a correction the date of the claim it corrects.
  roundsOn: string;
  // The date the claim is due by: fixed when it was added, from the terms for its person's grade on its date.
  dueBy: string;
  // The date the claim was deferred until; null for one never deferred. See deferred().
  deferredUntil: string | null;
  // How many proofs the claim has. One whose due is above the proof threshold in force on its date cannot be
  // settled or approved while it has none.
  proofs: number;
  // The number of the claim this one was split off; null for a claim not split off another.
  splitFrom: string | null;
  // The claim's status log, oldest first: a line for each status it has had, from its DRAFT on.
  log: ClaimLogLine[];
  // The user whose open editor holds the claim, so no one else may edit it; null while none does.
  lockedBy: string | null;
}

